sourceCluster : VH → Fin r
  hostCluster : VG → Fin r
  source_independent : ∀ i, H.IsIndepSet {x | sourceCluster x = i}
  capacity : ∀ i, Fintype.card {x | sourceCluster x = i} ≤
    Fintype.card {v | hostCluster v = i}
