BlowUpInstance.tex_statement:
\begin{definition}
Let $H,G$ be finite graphs and let $R$ be a graph on $[r]$.  A blow-up instance consists of cluster maps $c_H:V(H)\to[r]$ and $c_G:V(G)\to[r]$.  Writing $X_i=c_H^{-1}(i)$ and $V_i=c_G^{-1}(i)$, it is required that every $X_i$ is independent in $H$, that $|X_i|\leq|V_i|$ for every $i$, and that every edge $xy\in E(H)$ satisfies $c_H(x)c_H(y)\in E(R)$.  The fibers of the two cluster maps are, intrinsically, partitions of the respective vertex sets.
\end{definition}

BlowUpReductionToAuxiliary.tex_statement:
\begin{lemma}[Reduction to the auxiliary blow-up lemma]
Let $\Delta\geq1$ and $0<\varepsilon'<1$, $0<d'<d^2/2$ with $d\leq1$.  There is $0<\varepsilon<\varepsilon'$, depending only on these displayed parameters, such that for every $r$ there is $n_0$ such that, whenever $n\geq n_0$ and
\[
 (H,G,R,(X_i)_{i\in[r]},(V_i)_{i\in[r]},(A^i)_{i\in[r]})
\]
is a lower-$(\varepsilon,d)$-super-regular blow-up instance with lower-super-regular candidacy graphs, $\Delta(H),\Delta(R)\leq\Delta$, and $|X_i|=|V_i|=n$, there is an $(\varepsilon',d')$-super-regular refined instance
\[
 (H',G',R',(X_{i,j}),(V_{i,j}),(A'^{i,j}))
 \qquad(i\in[r],\ j\in[\Delta^2])
\]
with all of the following properties:
\begin{itemize}
\item $H\subseteq H'$, $G'\subseteq G$, and $A'^{i,j}\subseteq A^i$;
\item the refined source and host cluster maps project exactly to the original cluster maps, equivalently $X_i=\mathbin{\dot\bigcup}_{j=1}^{\Delta^2}X_{i,j}$ and $V_i=\mathbin{\dot\bigcup}_{j=1}^{\Delta^2}V_{i,j}$;
\item $(i,j)(i',j')\in E(R')$ if and only if $ii'\in E(R)$, and $\Delta(H'),\Delta(R')\leq\Delta^3$;
\item with $n'=\lfloor n/\Delta^2\rfloor$, one has $|X_{i,j}|=|V_{i,j}|\in\{n',n'+1\}$;
\item for every edge $(i,j)(i',j')$ of $R'$, the graph $H'[X_{i,j},X_{i',j'}]$ is a \noderef{SaturatingSourcePair}; for every nonedge it is empty.
\end{itemize}
Here lower and ordinary super-regularity are the predicates of \noderef{InstanceLowerSuperRegular}, \noderef{CandidacyLowerSuperRegular}, \noderef{InstanceSuperRegular}, and \noderef{CandidacySuperRegular}.
\end{lemma}

CandidacyLowerSuperRegular.tex_statement:
\begin{definition}
For a blow-up instance with candidacy system \noderef{CandidacySystem}, the candidacy graphs are lower-$(\varepsilon,d)$-super-regular if, for every cluster index $j$, the bipartite graph $A^j$ of allowed pairs between $X_j$ and $V_j$ is lower-$(\varepsilon,d)$-super-regular in the sense of \noderef{LowerSuperRegularPair}.
\end{definition}

CandidacySuperRegular.tex_statement:
\begin{definition}
For a blow-up instance with candidacy system \noderef{CandidacySystem}, the candidacy graphs are $(\varepsilon,d)$-super-regular if, for every cluster index $j$, the bipartite graph $A^j$ induced by the allowed pairs between $X_j$ and $V_j$ is $(\varepsilon,d)$-super-regular in the sense of \noderef{SuperRegularPair}.
\end{definition}

CandidacySystem.lean_statement:
structure CandidacySystem {r : ℕ} {VH VG : Type*} [Fintype VH] [Fintype VG]
    {H : SimpleGraph VH} {G : SimpleGraph VG} {R : SimpleGraph (Fin r)}
    (B : BlowUpInstance r VH VG H G R) where

CandidacySystem.tex_statement:
\begin{definition}
For a blow-up instance \noderef{BlowUpInstance}, a system of candidacy graphs is a family of bipartite edge relations $A^i\subseteq X_i\times V_i$, one for each $i\in[r]$.  Equivalently, it is a single relation $A(x,v)$ such that $A(x,v)$ can hold only when $x\in X_i$ and $v\in V_i$ for the same index $i$; the edges with endpoints in $X_i,V_i$ form the candidacy graph $A^i$.
\end{definition}

ClusterwiseDeletionBuffer.tex_proof:
\begin{proof}
For each $i$, choose exactly $|V_i|-m$ vertices from $X_i$; this is possible because $|X_i|=|V_i|$ and $m\leq|V_i|$.  The source fibers are disjoint, so the union of these choices is a set $X$ having the asserted equality in every cluster, and the hypothesis $|V_i|-m\leq k$ gives the first bound.

Fix $i$ and count ordered pairs $(x,y)$ with $x\in X'\cap X_i$, $y\in X$, and $xy\in E(H)$.  Every $x\in X'\cap X_i$ occurs in at least one such pair, by the definition of $X'$.  If $y\in X_j$ occurs, the reduced-support axiom in \noderef{BlowUpInstance} gives $ij\in E(R)$.  There are at most $\Delta$ possible clusters $j$, because $\Delta(R)\leq\Delta$.  For each such $j$ there are at most $k$ choices for $y\in X\cap X_j$, and each $y$ has at most $\Delta$ neighbors because $\Delta(H)\leq\Delta$.  Thus the number of pairs, and hence $|X'\cap X_i|$, is at most $\Delta\,k\,\Delta=\Delta^2k$.
\end{proof}

CompatibleEmbedding.tex_statement:
\begin{definition}
Given a blow-up instance with candidacy graphs \noderef{CandidacySystem}, an injective graph homomorphism $\varphi:H\hookrightarrow G$ is \emph{compatible} if $x\varphi(x)$ is an edge of $A^i$ for every $i\in[r]$ and every $x\in X_i$. Here, as in the paper, an embedding preserves source edges but need not reflect host edges; in Mathlib this is a \texttt{SimpleGraph.Copy}, not an induced graph embedding.
\end{definition}

CompleteRowPadding.tex_statement:
\begin{lemma}[Lower super-regularity under complete-row padding]
Let $L,Q$ be finite vertex sets of a simple graph $F$, let $e$ inject its vertex set into that of a simple graph $F^+$, and let $D$ be a finite vertex set disjoint from $e(L)$. Let $\varepsilon,\eta,d$ be extended nonnegative reals. Suppose $|e(L)\cup D|=|Q|$, adjacency between $e(L)$ and $e(Q)$ agrees exactly with adjacency between $L$ and $Q$, and every vertex of $D$ is adjacent to every vertex of $e(Q)$. If $(L,Q)$ is lower-$(\varepsilon,d)$-super-regular, $0<\varepsilon\leq\eta^2$, $\eta\leq1$, and $d\leq1$, then $(e(L)\cup D,e(Q))$ is lower-$(\eta,d)$-super-regular.
\end{lemma}

CylinderEvent.tex_statement:
\begin{definition}
For arbitrary types $X,Y$, a natural number $s$, and maps $x:\operatorname{Fin}(s)\to X$ and $y:\operatorname{Fin}(s)\to Y$, the cylinder event $\operatorname{Cyl}(x,y)$ is the set of all functions $f:X\to Y$ such that $f(x(i))=y(i)$ for every $i\in\operatorname{Fin}(s)$.  No finiteness or distinctness assumption is part of this definition.  The vertex-spread application in the paper specializes it to finite $X,Y$ and distinct entries of $x$.
\end{definition}

EquitableSquareColoring.tex_proof:
\begin{proof}
Fix $i$ and form the graph $Q_i$ on $X_i$ in which two distinct vertices are adjacent when their distance in $H$ is at most two.  Since $X_i$ is independent by \noderef{BlowUpInstance}, a vertex $x\in X_i$ has no distance-one neighbor in $X_i$.  Each of its at most $\Delta$ neighbors has at most $\Delta-1$ further neighbors other than $x$, so $d_{Q_i}(x)\leq\Delta(\Delta-1)<\Delta^2$.

Apply the Hajnal--Szemer\'edi equitable-coloring theorem to $Q_i$ with $\Delta^2$ colors: a finite graph of maximum degree strictly below $k$ has a proper $k$-coloring whose color-class sizes differ by at most one.  Thus the color classes have sizes $\lfloor n/\Delta^2\rfloor$ or $\lceil n/\Delta^2\rceil$, and the latter is either the former or one larger.  A proper color class in $Q_i$ contains neither an $H$-edge nor two vertices with a common $H$-neighbor, by the definition of $Q_i$.  Choose such a coloring independently for every finite cluster and combine them into the asserted map $c$.
\end{proof}

EquitableSquareColoring.tex_statement:
\begin{lemma}[Equitable square coloring]
Let $H$ be the source graph of a blow-up instance \noderef{BlowUpInstance}, suppose $\Delta(H)\leq\Delta$ with $\Delta\geq1$, and suppose every source cluster $X_i$ has size $n$.  There is a map $c:V(H)\to[\Delta^2]$ such that every fiber $X_{i,j}:=\{x\in X_i:c(x)=j\}$ has size $\lfloor n/\Delta^2\rfloor$ or $\lfloor n/\Delta^2\rfloor+1$, and any two distinct vertices in the same $X_{i,j}$ are nonadjacent in $H$ and have no common neighbor in $H$.
\end{lemma}

ExtendUpdatedPartialEmbedding.tex_proof:
\begin{proof}
Define $h(z)=f(z)$ for $z\in X$, define $h(z)=g(z)$ for $z\in Y$, and assign arbitrary values away from $X\cup Y$.  The first two clauses are unambiguous because $X$ and $Y$ are disjoint.

We first prove injectivity on $X\cup Y$.  Two vertices both in $X$ have distinct images by the injectivity field of \noderef{PartialCompatibleEmbedding} for $f$, and two vertices both in $Y$ have distinct images by the corresponding field for $g$.  If $x\in X$ and $y\in Y$, compatibility of $g$ with \noderef{UpdatedCandidacy} includes the condition $g(y)\notin f(X)$.  Hence $g(y)\ne f(x)$.  These three cases prove that $h$ is injective on its domain.

Next let $zz'$ be an edge of $H$ with both endpoints in $X\cup Y$.  If both endpoints lie in $X$, then $h(z)h(z')$ is an edge of $G$ because $f$ is a partial embedding.  If both lie in $Y$, the same conclusion follows because $g$ is a partial embedding.  In the remaining case, symmetry permits us to write the endpoints as $x\in X$ and $y\in Y$.  Compatibility of $g$ with the updated candidacy system says that for every already embedded neighbor $x'\in X$ of $y$, the pair $g(y)f(x')$ is an edge of $G$.  Taking $x'=x$ shows that $h(y)h(x)$ is an edge.  Thus $h$ preserves every edge induced by $X\cup Y$.

Finally, for $x\in X$, the pair $(x,h(x))=(x,f(x))$ is allowed by the original candidacy system because $f$ is compatible.  For $y\in Y$, compatibility of $g$ with the updated system includes, as one of the defining conjuncts of \noderef{UpdatedCandidacy}, that $(y,g(y))$ is allowed by the original system.  Hence $h$ is compatible with the original candidacy system throughout $X\cup Y$.  Together with injectivity and edge preservation this gives the required partial compatible embedding, and its definition gives the two asserted restriction identities.
\end{proof}

ExtendUpdatedPartialEmbedding.tex_statement:
\begin{lemma}[Extension by an updated partial embedding]
Let $f$ be a partial compatible embedding in the sense of \noderef{PartialCompatibleEmbedding} on a vertex set $X$, and let $Y$ be disjoint from $X$.  If $g$ is a partial compatible embedding on $Y$ for the updated candidacy system $A_f$ from \noderef{UpdatedCandidacy}, then there is a partial compatible embedding $h$ on $X\cup Y$ which agrees with $f$ on $X$ and with $g$ on $Y$.
\end{lemma}

FilteredProductRowCount.tex_proof:
\begin{proof}
Write the cardinality of a finite set as the sum of one over its elements.
The left side is therefore $\sum_{x\in U}\sum_{y\in W}\mathbf1_{P(x,y)}$.
For each fixed $x$, the inner sum counts exactly the elements $y\in W$ satisfying $P(x,y)$.
Summing those cardinalities over $U$ gives the asserted equality.
\end{proof}

InstanceLowerRegular.tex_statement:
\begin{definition}
A blow-up instance \noderef{BlowUpInstance} is host-lower-$(\varepsilon,d)$-regular if, for every edge $ij$ of the reduced graph $R$, the host clusters $V_i$ and $V_j$ form a lower $(\varepsilon,d)$-regular pair in $G$ in the sense of \noderef{LowerRegularPair}.
\end{definition}

InstanceLowerSuperRegular.tex_statement:
\begin{definition}
A blow-up instance \noderef{BlowUpInstance} is host-lower-$(\varepsilon,d)$-super-regular if, for every edge $ij$ of the reduced graph $R$, the host clusters $V_i$ and $V_j$ form a lower $(\varepsilon,d)$-super-regular pair in $G$ in the sense of \noderef{LowerSuperRegularPair}.
\end{definition}

InstanceSuperRegular.tex_statement:
\begin{definition}
A blow-up instance \noderef{BlowUpInstance} is host-$(\varepsilon,d)$-super-regular if, for every edge $ij$ of the reduced graph $R$, the host clusters $V_i$ and $V_j$ form an $(\varepsilon,d)$-super-regular pair in $G$ in the sense of \noderef{SuperRegularPair}.
\end{definition}

LowerRegularPair.tex_statement:
\begin{definition}
Let $G$ be a simple graph on an arbitrary vertex type, let $V_1,V_2$ be arbitrary finite vertex subsets, and let $\varepsilon,d$ be arbitrary extended nonnegative reals.  The ordered pair $(V_1,V_2)$ is lower $(\varepsilon,d)$-regular if every finite $U\subseteq V_1$ and $W\subseteq V_2$ satisfying $|U|>\varepsilon|V_1|$ and $|W|>\varepsilon|V_2|$ has $d_G(U,W)\geq d-\varepsilon$, where density is as in \noderef{PairDensity}.  The paper uses this predicate for finite ambient graphs, disjoint cluster fibers, $\varepsilon>0$, and $0<d<1$.
\end{definition}

LowerSuperRegularDeletionSlicing.tex_proof:
\begin{proof}
The required lower regularity is an explicit hypothesis; this is the usual slicing output, and is deliberately not inferred from degree information.  If $u\in U\setminus D_U$, lower super-regularity of the original pair, as defined in \noderef{LowerSuperRegularPair}, gives at least $(d-\varepsilon)|W|$ neighbors in $W$.  Deleting $D_W$ removes at most $|D_W|$ of them.  The first displayed inequality therefore leaves at least $(d'-\varepsilon')|W\setminus D_W|$ neighbors.  Interchanging the two sides and using the second inequality proves the corresponding bound for every $w\in W\setminus D_W$.  Together with the assumed residual lower regularity these are precisely the three clauses of lower $(\varepsilon',d')$-super-regularity.
\end{proof}

LowerSuperRegularPair.tex_statement:
\begin{definition}
Let $G$ be a simple graph on an arbitrary vertex type, let $V_1,V_2$ be arbitrary finite vertex subsets, and let $\varepsilon,d$ be arbitrary extended nonnegative reals.  The ordered pair $(V_1,V_2)$ is lower $(\varepsilon,d)$-super-regular if it is lower $(\varepsilon,d)$-regular in the sense of \noderef{LowerRegularPair}, every $v\in V_1$ has at least $(d-\varepsilon)|V_2|$ neighbors in $V_2$, and every $w\in V_2$ has at least $(d-\varepsilon)|V_1|$ neighbors in $V_1$.  The paper uses this predicate for finite ambient graphs, disjoint cluster fibers, $\varepsilon>0$, and $0<d<1$.
\end{definition}

MatchingInducedGraph.tex_statement:
\begin{definition}
Let $W_1,W_2,W_3$ be finite vertex sets, let $F_{13}$ and $F_{23}$ be graphs on the corresponding pairs, and let $\sigma:W_1\to W_2$ be an arbitrary map.  The $\sigma$-induced graph $A_\sigma$ is the bipartite graph on the disjoint-union copy $W_1\sqcup W_3$ in which the copy of $v_1\in W_1$ is adjacent to the copy of $v_3\in W_3$ exactly when $v_1v_3\in E(F_{13})$ and $\sigma(v_1)v_3\in E(F_{23})$.  The paper, and the node \noderef{NearEqualFourGraphs}, specialize this construction to the case in which $\sigma$ is a perfect matching in $F_{12}$.  In that case it is the paper's spanning subgraph of $F_{13}$, represented here on a disjoint union so that its two bipartition classes are definitionally disjoint.
\end{definition}

MatchingInducedLeftRowDeletion.tex_proof:
\begin{proof}
Write $L'=L\setminus\{x\}$.  Since $x\in L$, $|L'|=m$; the right part is literally the same $R$, not an isomorphic replacement.  Every vertex of $L'$ has exactly its old neighborhood in $R$, so its degree window remains valid after enlarging the error from $\varepsilon$ to $\varepsilon'$.  A vertex of $R$ loses at most the single neighbor $x$.  Its old degree differs from $d(m+1)$ by at most $\varepsilon(m+1)$, whereas its new target is $dm$.  Since $d,\varepsilon\leq1$, the total endpoint error is at most $\varepsilon m+2$, and the inequality $\varepsilon+2/m\leq\varepsilon'$ places the new degree in $[(d-\varepsilon')m,(d+\varepsilon')m]$.  This proves both degree sides.

For regularity, take $U\subseteq L'$ and $Z\subseteq R$ with
$|U|>\varepsilon'|L'|=\varepsilon'm$ and $|Z|>\varepsilon'|R|$.  Since $U\subseteq L$ and $\varepsilon'>\varepsilon$, the right threshold is already stronger than the old one.  On the left, the displayed strict inequality gives $|U|>\varepsilon'm>\varepsilon(m+1)$: indeed the second slack assumption implies $(\varepsilon'-\varepsilon)m\geq1/\varepsilon'\geq1$, and hence $\varepsilon'm\geq\varepsilon m+1\geq\varepsilon(m+1)$.  Thus the old $(\varepsilon,d)$-regularity applies directly to the very same pair $(U,Z)$.  Deleting the row removed no edge having one endpoint in $U\subseteq L'$ and the other in $Z$, so its pair density in the restricted graph is unchanged and lies in $[d-\varepsilon,d+\varepsilon]\subseteq[d-\varepsilon',d+\varepsilon']$.  This proves regularity and, with the two degree calculations, \noderef{SuperRegularPair} on the exact residual parts.
\end{proof}

MatchingInducedUpdatedCandidacyTransport.tex_proof:
\begin{proof}
By the displayed adjacency equivalence and the definition of \noderef{MatchingInducedGraph}, for every $x\in L_1$ and $z\in R$ the vertices $\operatorname{inl}(x)$ and $\operatorname{inr}(z)$ are adjacent in the matching-induced graph if and only if $\tau(x)$ and $z$ are adjacent in $A'$.  The forward directions of the two membership equivalences put every $\tau(x)$ in $L'$ and every coerced $z$ in $R'$; their reverse directions say that every member of $L'$ and $R'$ arises in this way.  Since $\tau$ and subtype coercions are injective, these maps are bijections of the displayed parts.

It remains to verify rather than merely invoke invariance.  For subsets $P\subseteq L'$ and $Q\subseteq R'$, take their inverse images $\widetilde P\subseteq L_1$ and $\widetilde Q\subseteq R$.  The forward membership implications put the images of these inverse images in $P$ and $Q$, while the reverse implications show that every element of $P$ and $Q$ is hit; injectivity makes both restrictions bijective.  Hence $|P|=|\widetilde P|$ and $|Q|=|\widetilde Q|$, and applying the same argument to the full parts gives $|L'|=|L_1|$ and $|R'|=|R|$.  The edgewise equivalence gives a bijection between the edges of $A'$ from $P$ to $Q$ and the matching-induced edges from $\widetilde P$ to $\widetilde Q$.  Consequently their edge counts and pair densities agree.  Using the full-part cardinality equalities, the size hypotheses in regularity transfer in both directions, so the $(\varepsilon,d)$-regularity clause transfers to $A'$.

For $y\in L'$, the reverse left-membership implication supplies $x\in L_1$ with $y=\tau(x)$, and injectivity of $\tau$ makes it unique.  The edgewise equivalence together with both directions of the right-membership equivalence bijects $N_{A'}(y)\cap R'$ with the matching-induced neighborhood of $\operatorname{inl}(x)$ in the right part.  Their cardinalities are equal; since $|R'|=|R|$, both the lower and upper $(d\pm\varepsilon)|R'|$ degree bounds transfer.  For $z\in R'$, the reverse right-membership implication supplies its unique preimage in $R$.  Applying the adjacency equivalence for every $x$ and both directions of the left-membership equivalence bijects $N_{A'}(z)\cap L'$ with the corresponding matching-induced neighborhood.  Since $|L'|=|L_1|$, both degree bounds on this side transfer as well.  These regularity and two degree conclusions are exactly \noderef{SuperRegularPair} for $(L',R')$.
\end{proof}

NearEqualDegreeCodegreeRegularityCriteri.tex_statement:
\begin{lemma}[Near-equal degree--codegree criterion]
Let $U,W$ be disjoint, let $|U|=m\geq2$, and let $|W|\in\{m-1,m,m+1\}$.  Suppose $0\leq\delta\leq p\leq1$, $\eta\leq1$, $1\leq\delta m$, and $32\delta\leq\eta^5$.  In a bipartite graph $G[U,W]$, call an ordered pair $(w,w')\in W^2$ bad if either endpoint has fewer than $(p-\delta)m$ neighbors in $U$, or if the pair has more than $(p+\delta)^2m$ common neighbors in $U$.  If at most $6\delta|W|^2$ ordered pairs are bad, then $(U,W)$ is $(\eta,p)$-regular in the sense of \noderef{RegularPair}.
\end{lemma}

OneIndexBadPairCounting.tex_statement:
\begin{lemma}[One-index near-equal bad-pair counting]
Let $|W_1|=|W_2|=n$ and $|W_3|\in\{n-1,n,n+1\}$. Let $0\leq\varepsilon\leq1$, let $d_{13},d_{23}\leq1$, and suppose $F_{13}[W_1,W_3]$ and $F_{23}[W_2,W_3]$ are $(\varepsilon,d_{13})$- and $(\varepsilon,d_{23})$-super-regular. Call $(x,v)$ bad when its common-neighborhood size is outside $(d_{13}d_{23}\pm2\varepsilon)|W_3|$. If $U\subseteq W_1$ and $W\subseteq W_2$ satisfy $|U|,|W|>2\sqrt\varepsilon n$, then at most a $\sqrt\varepsilon$ proportion of $U\times W$ is bad.
\end{lemma}

